head.script:
scwin.screenId = "jldstf10099";

///////// 1. 변수 및 선언 영역 /////////

scwin.gPvd = undefined;

scwin.gAcptNo = undefined;

scwin.gViewerStat = undefined;

scwin.gAskScrenID = undefined;


///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10099.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.getParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getParam = function () {
    /* sdd-asis-lifecycle:begin fn_getParam — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const pvd = scwin.getProvider();
    const Temp0 = pvd.split("&")[0];
    scwin.gAcptNo = Temp0.split("=")[1];
    scwin.gViewerStat = "P";
    gAccssAuthTpCd = "01";
    scwin.gAskScrenID = "ULDSTF10099.gfm";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getProvider
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getProvider = function () {
    /* sdd-asis-lifecycle:begin fn_GetProvider — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = $c.frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.closeWin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.closeWin = function () {
    /* sdd-asis-lifecycle:begin fn_CloseWin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.frame.CloseFrame();
    /* sdd-asis-lifecycle:end */
};
